// A dispatch uncertainty belongs to a request, never to the whole chat.
const D=(()=>{
 const fs=require('fs'),root='/files/.telegram-ui';
 const valid=id=>typeof id==='string'&&/^tg-0-[0-9]+$/.test(id);
 const read=p=>fs.existsSync(p)?JSON.parse(fs.readFileSync(p,'utf8')):null;
 const fp=r=>JSON.stringify([r.image,r.prompt.trim(),(r.negative_prompt??'').trim(),r.duration_seconds,...(r.aspect_ratio===undefined?[]:[r.aspect_ratio])]);
 const request=r=>!!r&&valid(r.request_id)&&(r.aspect_ratio===undefined||['9:16','16:9'].includes(r.aspect_ratio))&&typeof r.image==='string'&&/^[A-Za-z0-9][A-Za-z0-9_-]*\.(png|jpe?g|webp)$/i.test(r.image)&&typeof r.prompt==='string'&&!!r.prompt.trim()&&r.prompt.length<=3000&&typeof(r.negative_prompt??'')==='string'&&[2,4,6,8,10].includes(r.duration_seconds);
 function lookup(id,r){
  if(!valid(id))return {kind:'invalid'};
  let reg;try{reg=read(root+'/scheduler/jobs/'+id+'.json');}catch(_){return {kind:'corrupt'};}
  if(!reg)return {kind:'missing'};
  if(reg.request_id!==id)return {kind:'conflict',reg};
  if(reg.cleared_at)return {kind:'cleared',reg};
  if(['deleted','deleting'].includes(reg.status))return {kind:reg.status,reg};
  if(r&&reg.fingerprint!==fp(r))return {kind:'conflict',reg};
  return {kind:'registered',reg};
 }
 function ownsSubmission(state,id){return state.submitting_request_id===id||(!state.submitting_request_id&&state.last_job?.request_id===id&&request(state.last_job.request)&&typeof state.submitting_draft?.prompt==='string'&&fp(state.submitting_draft)===fp(state.last_job.request));}
 function sync(state){
  state.dispatches??={};
  const last=state.last_job;
  if(last&&['claiming','uncertain'].includes(last.status)&&request(last.request)&&!state.dispatches[last.request_id])state.dispatches[last.request_id]={request:last.request,status:last.status,created_at:last.created_at??new Date().toISOString()};
  for(const [id,e] of Object.entries(state.dispatches)){
   if(!request(e.request))continue;
   const found=lookup(id,e.request);
   if(found.kind==='registered'){
    e.status=found.reg.status;e.main_execution_id=found.reg.execution_id;e.prompt_id=found.reg.prompt_id??null;
    if(state.last_job?.request_id===id){state.last_job.status=e.status;state.last_job.main_execution_id=e.main_execution_id;state.last_job.prompt_id=e.prompt_id;}
    if(ownsSubmission(state,id)){delete state.submitting_draft;delete state.submitting_request_id;}
   }else if(['deleted','deleting','cleared'].includes(found.kind)){
    if(ownsSubmission(state,id)){delete state.submitting_draft;delete state.submitting_request_id;}
    delete state.dispatches[id];if(state.last_job?.request_id===id)state.last_job=null;
   }else if(found.kind==='conflict'||found.kind==='corrupt')e.status='registration_conflict';
   else if(['claiming','uncertain','accepted'].includes(e.status))e.status='uncertain';
  }
  return state;
 }
 function saved(state,id){
  if(!valid(id))return null;
  let e=state.dispatches?.[id];
  if(!e){const a=read(root+'/jobs/'+id+'.json');if(request(a?.request))e={request:a.request,draft:a.draft,status:'uncertain'};}
  if(!e&&state.last_job?.request_id===id&&request(state.last_job.request))e={request:state.last_job.request,status:state.last_job.status};
  return e&&request(e.request)?e:null;
 }
 return {lookup,sync,saved,fp,valid,request,ownsSubmission};
})();

const fs=require('fs');
