const labels={recovering:"recovering after restart",recovery_pending:"waiting for automatic resubmission",recovery_needs_restart:"recovery: restart Comfy to resolve an uncertain submission",recovery_needs_data:"recovery: check the original parameters",recovery_needs_image:"recovery: send the first frame again",recovery_needs_review:"recovery: check the final file",registered:'registrado',waiting_generation:"waiting for submission to Comfy",generation_submitting:"submitting generation",generating:"queued/generating LTX",awaiting_review:"waiting for your approval",waiting_postprocess:"waiting for post-processing",postprocess_waiting_for_idle:"waiting for the Comfy queue to finish",interpolating:"interpolation",upscaling:'upscale',finished:"completed",rejected:'rejeitado',failed:"failed",cancelled:"manually interrupted"};
let list=[];
if(fs.existsSync(root+'/jobs'))for(const name of fs.readdirSync(root+'/jobs')){
  if(!new RegExp('^tg-'+base.chat_id+'-[0-9]+\\.json$').test(name))continue;
  const j=JSON.parse(fs.readFileSync(root+'/jobs/'+name,'utf8'));if(!j.cleared_at&&!['deleted','deleting'].includes(j.status))list.push(j);
}
list.sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));
const open=list.filter(j=>!['finished','rejected','failed','cancelled'].includes(j.status));
const shown=[...open,...list.filter(j=>!open.includes(j))].slice(0,10);
let text='<b>📋 Jobs</b>\n'+(shown.length?shown.map(j=>`${esc(j.request_id)}\n↳ ${esc(labels[j.status]??j.status)}${j.request?.aspect_ratio?' · '+esc(j.request.aspect_ratio):''}${j.wait_detail&&['waiting_generation','waiting_postprocess','postprocess_waiting_for_idle'].includes(j.status)?"\n   Reason: "+esc(j.wait_detail):''}${j.history_poll?.unavailable&&['generating','interpolating','upscaling'].includes(j.status)?"\n   Monitoring: history temporarily unavailable ("+esc(j.history_poll.failures)+" attempt(s)); stage not resubmitted.":''}${j.recovery_wake_error?'\n   Supervisor: '+esc(j.recovery_wake_error):''}`).join('\n\n'):"No jobs visible in the list.");
text+=`\n\nOpen: ${open.length}. Showing up to 10 jobs.\nUse /retry REQUEST_ID to recover the parameters of a specific video.`;
if(fs.existsSync(root+'/control.json')){
  const c=JSON.parse(fs.readFileSync(root+'/control.json','utf8'));
  if(c.recovery_active)text+="\n\n♻️ Recovery in progress. Waiting for Comfy to become idle before reorganizing the queue.";
  if(!c.recovery_active&&(c.paused||c.lease?.blocked))text+="\n\n⚠️ Admission paused. Check the failure and reservation before releasing it.";
  const boot=fs.existsSync('/files/.telegram-ui/comfy-boot.json')?JSON.parse(fs.readFileSync('/files/.telegram-ui/comfy-boot.json','utf8')):null;
  if(boot?.boot_id&&c.reconciled_boot!==boot.boot_id)text+="\n\n♻️ The Comfy restart has not been reconciled yet. Use /recover and check that Video Queue - Automatic Recovery is published.";
  if(c.lease){text+="\nReservation: "+esc(c.lease.kind)+' — '+esc(c.lease.request_id);if(!list.some(j=>j.request_id===c.lease.request_id))text+="\n↳ Residual reservation for a request outside this list; it is not a task in the Comfy queue.";}
  if(c.stop_pending)text+="\n\n🛑 Stop awaiting confirmation.";
  if(c.stop_last_error)text+='\n'+esc(c.stop_last_error);
}
const stateFile=base.state_path??('/files/.telegram-ui/'+base.chat_id+'-'+base.user_id+'.json');
if(fs.existsSync(stateFile)){
 const ui=D.sync(JSON.parse(fs.readFileSync(stateFile,'utf8')));
 const pending=Object.entries(ui.dispatches??{}).filter(([id,e])=>['claiming','uncertain','registration_conflict'].includes(e.status)&&!['registered','deleted','deleting'].includes(D.lookup(id,e.request).kind));
 if(pending.length)text+="\n\n<b>Unconfirmed submissions: "+pending.length+'</b>\n'+pending.slice(0,5).map(([id])=>esc(id)).join('\n')+"\nThese do not block other videos. Use /retry REQUEST_ID to check the same request.";
}
text+=q.error||!Array.isArray(q.queue_running)||!Array.isArray(q.queue_pending)?"\n\nComfy is not responding.":'\n\nComfy: '+q.queue_running.length+" running; "+q.queue_pending.length+" queued.";
return [{json:{...base,text}}];

