const base=$('Handle Telegram Wizard').first().json,result=$input.first().json.dispatch_response??$input.first().json;
const id=base.request.request_id;
const r=S.tx(()=>{
 let fd;const lock=base.state_path+'.lock-'+RUNTIME;
 try{fd=S.fs.openSync(lock,'wx',0o600);}catch(e){if(e.code==='EEXIST')return {recorded:false};throw e;}
 try{
  const state=D.sync(S.read(base.state_path,{}));
  const found=D.lookup(id,base.request);
  const ack=!result.error&&['accepted','duplicate'].includes(result.status)&&result.request_id===id;
  const accepted=ack||['registered','cleared'].includes(found.kind);
  const deleted=['deleted','deleting'].includes(found.kind);
  const reason=String(result.error?.message??result.error??result.message??('HTTP '+(result.statusCode??result.httpCode??"unconfirmed"))).slice(0,350);
  const entry={...(state.dispatches?.[id]??{}),request:base.request,status:accepted?(found.reg?.status??'accepted'):'uncertain',updated_at:new Date().toISOString(),error:accepted?null:reason};
  if(!deleted&&!found.reg?.cleared_at){state.dispatches??={};state.dispatches[id]=entry;}
  if(state.last_job?.request_id===id&&!deleted){
   Object.assign(state.last_job,{status:entry.status,main_execution_id:found.reg?.execution_id??result.execution_id??null,prompt_id:found.reg?.prompt_id??result.prompt_id??null});
   if(accepted&&D.ownsSubmission(state,id)){delete state.submitting_draft;delete state.submitting_request_id;}
  }
  S.write(base.state_path,state);
  let text;
  if(deleted)text="🗑 This request was already deleted: "+id+". No new job was created.";
  else if(found.kind==='cleared')text="🧹 This request was already removed from the list: "+id+". Files preserved; no new job was created.";
  else if(accepted){
   const status=found.reg?.status??result.job_status??'registrado';
   text="✅ Job registered: "+id+"\nState: "+status+". You can prepare the next one. Use /queue or /status to track progress.";
   if(status==='failed')text+="\nThis job failed. Use /retry "+id+" to review and request another generation.";
  }else text="⚠️ Registration is still unconfirmed: "+id+"\nDetails: "+reason+"\nThis does not block other videos. Use /retry "+id+" to check/repeat only this registration with the same ID. A different ID will not be created accidentally.";
  const escape=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  return {recorded:true,text:escape(text)};
 }finally{S.fs.closeSync(fd);S.fs.unlinkSync(lock);}
});
return [{json:{...base,preview:false,recorded:r.recorded===true,...(r.recorded?{}:{dispatch_response:result}),text:r.text}}];

